import sqlite3
SQL="""CREATE TABLE IF NOT EXISTS local_taxon_candidates(id INTEGER PRIMARY KEY,region_id INTEGER NOT NULL REFERENCES regions(id),submitted_scientific_name VARCHAR(256) NOT NULL,submitted_identifier_scheme VARCHAR(64),submitted_identifier VARCHAR(128),canonical_scientific_name VARCHAR(256) NOT NULL,authorship VARCHAR(256),taxonomic_rank VARCHAR(32) NOT NULL,authoritative_identifier_scheme VARCHAR(64) NOT NULL,authoritative_identifier VARCHAR(128) NOT NULL,accepted_name_status VARCHAR(32) NOT NULL,accepted_authoritative_identifier VARCHAR(128),parent_authoritative_identifier VARCHAR(128),parent_name VARCHAR(256),provider VARCHAR(64) NOT NULL,provider_version VARCHAR(128) NOT NULL,provider_source_reference VARCHAR(512) NOT NULL,provider_artifact_reference VARCHAR(512) NOT NULL,provider_artifact_sha256 VARCHAR(64) NOT NULL,provider_content_fingerprint VARCHAR(64) NOT NULL,candidate_source VARCHAR(128) NOT NULL,candidate_provenance_json TEXT NOT NULL,reconciliation_result VARCHAR(24) NOT NULL,limitations_json TEXT NOT NULL,dependency_fingerprint VARCHAR(64) NOT NULL UNIQUE,workflow_status VARCHAR(24) NOT NULL DEFAULT 'READY_FOR_REVIEW',created_by VARCHAR(256) NOT NULL,created_at DATETIME NOT NULL,reviewed_by_user_id INTEGER REFERENCES users(id),reviewed_at DATETIME,approval_reference VARCHAR(256),approved_dependency_fingerprint VARCHAR(64),applied_at DATETIME,resulting_species_id INTEGER REFERENCES species(id),resulting_registry_entry_id INTEGER REFERENCES regional_taxon_registry(id),last_error TEXT)"""
def run_migration(c:sqlite3.Connection):
 existed=c.execute("select 1 from sqlite_master where type='table' and name='local_taxon_candidates'").fetchone() is not None
 with c:
  c.execute(SQL)
  for x in ('region_id','authoritative_identifier','workflow_status','dependency_fingerprint'):c.execute(f"create index if not exists ix_local_taxon_candidates_{x} on local_taxon_candidates({x})")
 return {'table_created':not existed}
